"""Self-contained local chat-style browser workspace."""

def dashboard_html() -> str:
    return '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Circuit Agent</title>
<style>
:root{color-scheme:dark;--bg:#121212;--panel:#1e1f20;--line:#333537;--text:#e8eaed;--muted:#9aa0a6;--accent:#8ab4f8;--user:#25354c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px Inter,ui-sans-serif,system-ui,sans-serif}.app{display:grid;grid-template-columns:280px minmax(0,1fr);min-height:100vh}.side{padding:20px;border-right:1px solid var(--line);background:#171717}.brand{font-size:18px;font-weight:700}.muted{color:var(--muted);font-size:13px;line-height:1.5}.main{max-width:900px;width:100%;margin:0 auto;display:flex;flex-direction:column;min-height:100vh}.chat{flex:1;padding:32px 24px 160px;overflow:auto}.message{max-width:760px;margin:0 auto 22px;padding:16px 18px;border-radius:14px;background:var(--panel);line-height:1.55;white-space:pre-wrap}.message.user{background:var(--user)}.who{font-size:12px;font-weight:700;color:var(--accent);margin-bottom:7px}.composer{position:fixed;bottom:20px;left:max(300px,calc((100vw - 900px)/2));right:max(20px,calc((100vw - 900px)/2));background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:10px;display:flex;gap:8px}.composer textarea{flex:1;resize:none;min-height:52px;background:transparent;color:var(--text);border:0;padding:10px;font:inherit}.composer textarea:focus{outline:0}button{border:0;border-radius:9px;background:var(--accent);color:#10213b;font-weight:650;padding:9px 12px;cursor:pointer}button.secondary{background:#303134;color:var(--text)}input,select,textarea{width:100%;background:#292a2d;border:1px solid var(--line);border-radius:8px;color:var(--text);padding:8px;margin:4px 0 10px;font:inherit}.card{border:1px solid var(--line);border-radius:12px;padding:13px;margin:18px 0}.card h2{font-size:14px;margin:0 0 9px}.status{font-size:12px;color:var(--muted)}details summary{cursor:pointer;color:var(--accent)}#spec{height:145px}@media(max-width:760px){.app{display:block}.side{border-right:0;border-bottom:1px solid var(--line)}.composer{left:14px;right:14px}.chat{padding:24px 14px 150px}}
</style></head><body><div class="app"><aside class="side"><div class="brand">Circuit Agent</div><p class="muted">Low-voltage educational simulation workspace. Simulation is not hardware safety certification.</p>
<div class="card"><h2>Model provider</h2><label class="muted">Provider</label><input id="provider" value="mock" placeholder="mock, openai, anthropic, google"><label class="muted">Model</label><input id="model" value="deterministic" placeholder="Model identifier"><label class="muted">API key (encrypted locally; never returned)</label><input id="apiKey" type="password" autocomplete="new-password" placeholder="Leave blank to keep current key"><label class="muted">Base URL (optional)</label><input id="baseUrl" placeholder="https://api.example.com"><div style="display:flex;gap:6px"><label class="muted">Temperature <input id="temperature" type="number" min="0" max="2" step="0.1" value="0.1"></label><label class="muted">Max tokens <input id="maxTokens" type="number" min="1" value="4096"></label></div><label class="muted"><input id="enabled" type="checkbox" checked style="width:auto"> Enabled</label><div><button onclick="saveModel()">Save model settings</button><button class="secondary" onclick="clearKey()">Clear API key</button></div><p id="modelState" class="status"></p></div>
<div class="card"><h2>Project</h2><input id="pid" placeholder="Project ID"><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="secondary" onclick="project('')">Status</button><button class="secondary" onclick="project('run')">Run</button><button class="secondary" onclick="project('resume')">Resume</button></div><p class="status">Approvals are recorded from the project draft below.</p></div>
<details class="card"><summary>Structured project draft</summary><textarea id="spec">{\n  "name": "Educational RC low-pass",\n  "request": "Create a 5 V educational RC low-pass simulation.",\n  "scope": "low_voltage_educational",\n  "simulator": "none",\n  "requirements": [],\n  "circuit_ir": {}\n}</textarea><button onclick="createProject()">Create project from draft</button><div style="margin-top:8px"><select id="subject"><option value="design">Design approval</option><option value="optimization">Optimization approval</option></select><input id="revision" type="number" value="1" min="1"><button class="secondary" onclick="approve()">Record approval</button></div></details></aside>
<main class="main"><section id="chat" class="chat"><div class="message"><div class="who">Circuit Agent</div>Describe the low-voltage educational circuit you want to explore. The chat records a safe local draft; structured project creation and simulation remain controlled by the workflow.</div></section><div class="composer"><textarea id="message" placeholder="Message Circuit Agent…" aria-label="Message"></textarea><button onclick="send()">Send</button></div></main></div>
<script>
const chat=document.querySelector('#chat');function add(role,text){const el=document.createElement('div');el.className='message '+(role==='You'?'user':'');el.innerHTML='<div class="who">'+role+'</div>';const body=document.createElement('div');body.textContent=text;el.appendChild(body);chat.appendChild(el);el.scrollIntoView({behavior:'smooth',block:'end'});}async function api(path,opts={}){const r=await fetch(path,opts),b=await r.json();if(!r.ok)throw Error(b.error||r.statusText);return b}async function loadModel(){try{const x=await api('/settings/model');provider.value=x.provider;model.value=x.model;baseUrl.value=x.base_url||'';temperature.value=x.temperature;maxTokens.value=x.max_tokens;enabled.checked=x.enabled!==false;modelState.textContent=(x.api_key_configured?'Encrypted API key saved. ':'No API key saved. ')+(x.adapter_available?'Local mock adapter available.':'Provider adapter is not installed.')}catch(e){modelState.textContent=e.message}}async function saveModel(){try{const x=await api('/settings/model',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:provider.value,model:model.value,api_key:apiKey.value,base_url:baseUrl.value,temperature:Number(temperature.value),max_tokens:Number(maxTokens.value),enabled:enabled.checked})});apiKey.value='';modelState.textContent=(x.api_key_configured?'Encrypted API key saved. ':'No API key saved. ')+(x.adapter_available?'Local mock adapter available.':'Provider adapter is not installed.');add('System','Model configuration saved: '+x.provider+' / '+x.model+'.')}catch(e){add('System','Settings error: '+e.message)}}async function clearKey(){try{await api('/settings/model',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider:provider.value,model:model.value,base_url:baseUrl.value,temperature:Number(temperature.value),max_tokens:Number(maxTokens.value),enabled:enabled.checked,clear_api_key:true})});apiKey.value='';modelState.textContent='API key cleared.';add('System','Stored API key cleared.')}catch(e){add('System','Settings error: '+e.message)}}async function send(){const box=document.querySelector('#message'),text=box.value.trim();if(!text)return;box.value='';add('You',text);try{const x=await api('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text})});add('Circuit Agent',x.content)}catch(e){add('System','Chat error: '+e.message)}}async function createProject(){try{const x=await api('/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:spec.value});pid.value=x.project_id;add('System','Project created: '+x.project_id)}catch(e){add('System','Project error: '+e.message)}}async function project(action){if(!pid.value.trim())return add('System','Enter a project ID first.');try{const path='/projects/'+encodeURIComponent(pid.value)+(action?'/'+action:'');const x=await api(path,{method:action?'POST':'GET'});add('Project',JSON.stringify(x,null,2))}catch(e){add('System','Project error: '+e.message)}}async function approve(){if(!pid.value.trim())return add('System','Enter a project ID first.');try{await api('/projects/'+encodeURIComponent(pid.value)+'/approvals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subject:subject.value,revision:Number(revision.value)})});add('System','Approval recorded.')}catch(e){add('System','Approval error: '+e.message)}}message.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}});loadModel();
</script></body></html>'''
